import{_ as t,c as a,o,ag as r}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{"subtitle":"Install Meloncart and get your store up and running."},"headers":[],"relativePath":"developer/installation.md","filePath":"developer/installation.md"}'),n={name:"developer/installation.md"};function s(i,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Getting started with Meloncart takes just a few steps. You&#39;ll set up October CMS, connect your project to the Marketplace, and add Meloncart along with a ready-made storefront theme.</p><h2 id="_1-try-the-demo-first" tabindex="-1">1. Try the Demo First <a class="header-anchor" href="#_1-try-the-demo-first" aria-label="Permalink to &quot;1. Try the Demo First&quot;">​</a></h2><p>Before setting anything up, take Meloncart for a spin. The live demo gives you full access to the backend admin panel and a working storefront, so you can explore products, orders, checkout and every feature covered in this documentation.</p><p>This is the fastest way to confirm that Meloncart is the right fit for your project, no installation required.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Visit the <a href="https://octobercms.com/demo/meloncart" target="_blank" rel="noreferrer">Meloncart demo</a> to explore the platform before committing to an install.</p></div><h2 id="_2-install-october-cms" tabindex="-1">2. Install October CMS <a class="header-anchor" href="#_2-install-october-cms" aria-label="Permalink to &quot;2. Install October CMS&quot;">​</a></h2><p>Meloncart runs on October CMS, a Laravel-based content management system. If you don&#39;t have an October CMS project yet, you&#39;ll need to set one up first.</p><p>There are several ways to get started:</p><ul><li><strong>Laravel installer</strong>: create a new project with <code>composer create-project october/october myproject</code></li><li><strong>Web installer</strong>: download the installer and follow the browser-based setup wizard</li><li><strong>Docker</strong>: use a Docker image for a containerized development environment</li></ul><p>Check the <a href="https://docs.octobercms.com/4.x/setup/installation.html" target="_blank" rel="noreferrer">October CMS installation guide</a> for detailed instructions and server requirements.</p><h2 id="_3-create-a-free-october-cms-account" tabindex="-1">3. Create a Free October CMS Account <a class="header-anchor" href="#_3-create-a-free-october-cms-account" aria-label="Permalink to &quot;3. Create a Free October CMS Account&quot;">​</a></h2><p>To install plugins from the Marketplace, you&#39;ll need an October CMS account. Registration is free and takes less than a minute.</p><ol><li>Visit <a href="https://octobercms.com" target="_blank" rel="noreferrer">octobercms.com</a> and create an account</li><li>Create a new project in your account dashboard</li><li>Generate a <strong>project key</strong>: this connects your local installation to the Marketplace</li></ol><p>Then attach the project key to your October CMS installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project:set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-project-ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>This unlocks access to the full plugin and theme ecosystem, including free community plugins and paid products like Meloncart.</p><h2 id="_4-add-meloncart-to-your-project" tabindex="-1">4. Add Meloncart to Your Project <a class="header-anchor" href="#_4-add-meloncart-to-your-project" aria-label="Permalink to &quot;4. Add Meloncart to Your Project&quot;">​</a></h2><p>With your project connected, you&#39;re ready to install Meloncart. Head to the October CMS Marketplace, add Meloncart to your project, and choose the Fresh Theme to get a complete working storefront out of the box.</p><ul><li><strong><a href="https://octobercms.com/plugin/meloncart-shop" target="_blank" rel="noreferrer">Meloncart</a></strong>: the core eCommerce plugin with products, orders, payments, shipping, and everything else</li><li><strong><a href="https://octobercms.com/theme/meloncart-fresh" target="_blank" rel="noreferrer">Fresh Theme</a></strong>: a fully functional reference storefront, ready to use as-is or customize to your needs</li></ul><p>All dependencies (payment processing, multi-currency support, customer accounts, and location data) are installed automatically. There&#39;s nothing extra to configure before you can start building.</p><h2 id="_5-sync-and-install" tabindex="-1">5. Sync and Install <a class="header-anchor" href="#_5-sync-and-install" aria-label="Permalink to &quot;5. Sync and Install&quot;">​</a></h2><p>From the October CMS backend, navigate to <strong>Settings → Updates &amp; Plugins</strong> and click <strong>Sync</strong> to pull everything down. This installs the Meloncart plugin, the Fresh Theme, and all dependencies in one step.</p><p>Alternatively, sync from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project:sync</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> october:migrate</span></span></code></pre></div><p>The migration creates all necessary database tables and seeds default data, including product types and initial order statuses.</p><h2 id="you-re-ready" tabindex="-1">You&#39;re Ready <a class="header-anchor" href="#you-re-ready" aria-label="Permalink to &quot;You&#39;re Ready&quot;">​</a></h2><p>Once the sync completes, a new <strong>Shop</strong> menu appears in the backend navigation. From here you can start adding products, configuring shipping and payment methods, and customizing your store.</p><ul><li><a href="/merchant/introduction.html">Merchant Guide</a>: learn how to manage your store day-to-day</li><li><a href="/developer/getting-started.html">Quick Start</a>: build your first storefront in 5 minutes</li><li><a href="/features/">Features</a>: explore everything Meloncart can do</li></ul>`,29)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
